{
  "claims": [
    {
      "claim": "The bill proposes to delete Tennessee Code Annotated Section 49-6-308.",
      "summary_quote": "This bill proposes to delete Tennessee Code Annotated Section 49-6-308.",
      "verdict": "supported",
      "source_quote": "Tennessee Code Annotated, Section 49-6-308, is amended by deleting the\n\nsection.",
      "error_type": "none",
      "rationale": "Section 1 expressly deletes the identified section."
    },
    {
      "claim": "The act would take effect immediately upon passage.",
      "summary_quote": "If passed, the act would take effect immediately.",
      "verdict": "contradicted",
      "source_quote": "This act takes effect upon becoming a law, the public welfare requiring it.",
      "error_type": "condition_exception",
      "rationale": "The effective-date trigger is becoming law, not merely passage. The summary substitutes passage for that condition."
    }
  ]
}
